it.each(["caller", "recipient", "failure"] as const)(
  "T-AC-09 T-CALL-PARITY distinguishes %s termination",
  async (actor) => {
    const { a, b, t, ids } = await setup();
    const conversationId = await a.mutation(api.conversations.createDM, { targetId: ids[1] });
    const id = await a.mutation(api.calls.start, {
      conversationId,
      kind: "video",
      session: "caller",
    });
    if (actor === "failure") await b.mutation(api.calls.accept, { id, session: "recipient" });
    if (actor === "recipient") await b.mutation(api.calls.hangup, { id });
    else
      await a.mutation(api.calls.hangup, {
        id,
        session: "caller",
        ...(actor === "failure" ? { reason: "connection-failed" as const } : {}),
      });
    const [row] = await t.run((ctx) => ctx.db.query("messages").collect());
    expect(row.callData?.outcome).toBe(
      actor === "caller" ? "canceled" : actor === "recipient" ? "declined" : "interrupted",
    );
  },
);
